import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../application/gamification_provider.dart';
import '../../domain/models/gamification_models.dart';

class LeaderboardScreen extends ConsumerStatefulWidget {const LeaderboardScreen({super.key});@override ConsumerState<LeaderboardScreen> createState()=>_LeaderboardScreenState();}
class _LeaderboardScreenState extends ConsumerState<LeaderboardScreen>{@override void initState(){super.initState();Future.microtask(()=>ref.read(gamificationProvider.notifier).refreshLeaderboard());}
@override Widget build(BuildContext context){final state=ref.watch(gamificationProvider);final data=state.leaderboard;return Scaffold(appBar:AppBar(title:const Text('العشرة الأوائل')),body:RefreshIndicator(onRefresh:()=>ref.read(gamificationProvider.notifier).refreshLeaderboard(),child:data==null?ListView(children:[const SizedBox(height:180),Center(child:state.error!=null?Column(children:[Text(state.error!),TextButton(onPressed:()=>ref.read(gamificationProvider.notifier).refreshLeaderboard(),child:const Text('إعادة المحاولة'))]):const CircularProgressIndicator())]):ListView(padding:const EdgeInsets.all(16),children:[Text('أكثر المستخدمين إنجازاً',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:4),Text('ترتيب كلي (كل الأوقات)',style:Theme.of(context).textTheme.bodySmall),const SizedBox(height:16),if(data.top.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(24),child:Text('لا توجد نتائج لعرضها'))),...data.top.map((entry)=>_row(context,entry,data.me.userId)),const SizedBox(height:16),if(data.me.rank==null)const Card(child:ListTile(leading:Icon(Icons.info_outline),title:Text('لم تسجل نشاطاً بعد'))),if(data.me.rank!=null&&!data.me.inTop)Card(child:ListTile(title:Text('مركزك الحالي: ${data.me.rank}'),subtitle:Text('المستوى ${data.me.level} • ${data.me.levelTitle}'),trailing:Text('${data.me.score} XP')))])));}
Widget _row(BuildContext context,LeaderboardEntry e,int me)=>Card(color:e.userId==me?Theme.of(context).colorScheme.primaryContainer:null,child:ListTile(leading:CircleAvatar(child:Text('${e.rank}')),title:Text(e.name),subtitle:Text('المستوى ${e.level} • ${e.levelTitle}'),trailing:Text('${e.score} XP')));}
